import test from 'node:test';
import assert from 'node:assert/strict';
import {slug} from '../src/slug.mjs';
test('independent label normalization acceptance',()=>{
 assert.equal(slug('  HeLLo__ world  '),'hello-world');
 assert.equal(slug('x--y'),'x--y');
 assert.equal(slug('a\tb\nc'),'a-b-c');
 assert.equal(slug('  '),'');
 assert.throws(()=>slug(null),TypeError);
 assert.throws(()=>slug(42),TypeError);
});
